//   - the head's check runs (bridge tool — the same REST list
//     computePrStatus falls back to);
//   - the head's run rollup (headWorkflowRunsSafe) as the resolver source:
//     a check-run's backing run is looked up BY ID (parsed from its
//     details_url); ABSENT from the head's list is the 404-equivalent
//     (deleted runs simply do not appear).
// Probe failure on EITHER side ⇒ null (caller keeps the legacy behavior —
// the green-cover skip stands; a degraded read must not turn into a
// re-dispatch churn, and the next tick retries with a healthy API).

function headCheckRunsSafe(repoInfo, headSha) {
    try {
        var res = github_get_commit_check_runs({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            commitSha: headSha
        });
        var parsed = mcpParse(res);
        return (parsed && parsed.check_runs) || [];
    } catch (e) {
        console.warn('  ⚠️  head check-run probe failed: ' + (e.message || e));
        return null;
    }
}

function headCheckRunZombies(repoInfo, headSha) {
    // → null (probe degraded — caller keeps legacy behavior) | the
    // classify() result {zombies, live, settled, unresolvable}.
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    if (!checkRuns.length) return { zombies: [], live: 0, settled: 0, unresolvable: 0 };
    var runs = headWorkflowRunsSafe(repoInfo, headSha);
    if (runs === null) return null;
    var byId = {};
    runs.forEach(function (r) {
        if (r && r.id !== undefined && r.id !== null) byId[String(r.id)] = r;
    });
    return checkRunZombiesModule.classify(checkRuns, function (runId) {
        var hit = byId[String(runId)];
        return hit === undefined ? null : hit;
    }, Date.now(), {
        staleNoRunnerMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieStaleMinutes,
        runConcludedGraceMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieGraceMinutes
    });
}


function hasActiveHeadRun(runs) {
    // hasActiveDispatchedRun semantics, widened to every run on the head:
    // any queued/in-progress/waiting/pending run means the state is about
    // to move on its own (a fresh kicker stamps the contexts, a validation
    // dispatch re-runs them) — rerunning cancelled runs under it would
    // only stack. Takes the pre-fetched head rollup (the action fetches
    // once and shares it with the target mapping — #695 review); a null
    // (failed probe) reads as no active run — fail OPEN. The ACTIVE
    // vocabulary comes from js/common/validationLiveness.js (gh-821 round-2
    // review: one constant, not parallel inline lists that drift).
    return (runs || []).some(function (r) {
        return validationLivenessModule.ACTIVE_RUN_STATES.indexOf(r.status) !== -1;
    });
}

// gh-798 (live fa PR #1420 rework leg, run 37828431528): the in-flight-leg
// exclusion for update_branch. A rework/review ai-teammate leg dispatched
// with workflowRef={branch} lands ON the PR head (its run head_sha IS the
// PR head), so an ACTIVE run of the leg workflow in the head rollup means
// the head is owned mid-run — the leg's timer pushes WIP auto-saves to that
// ref, and a silent refresh merged under it rejects the leg's next push
// non-fast-forward ("timer: git push failed" surfaced to the running
// agent). Same invariant as the ai_validating exclusion: a head with a leg
// in flight must not move. hasActiveHeadRun semantics (any
// queued/in_progress/waiting/pending run), NARROWED to the leg workflow
// path so unrelated CI on the head never blocks freshness, plus the same
// stale-zombie window the dispatch guard applies (a leg stuck 'queued' for
// hours ages out). Takes the pre-fetched head rollup (headWorkflowRunsSafe —
// the probe itself fails CLOSED in update_branch, unlike the rerun rule's
// fail-open read: one deferred refresh costs a tick, racing a live leg
// costs the leg's whole push stream).
function hasActiveLegRun(runs, workflowFile) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        var status = r.status;
        if (status !== 'queued' && status !== 'in_progress' &&
            status !== 'waiting' && status !== 'pending') return false;
        if (status !== 'in_progress' && isStaleNonRunningWorkflowRun(r, status)) return false;
        var p = String(r.path || '');
        return p.length >= suffix.length &&
            p.slice(p.length - suffix.length) === suffix;
