                    try {
                        var cmd = 'gh api -X POST repos/' + repoInfo.owner +
                                  '/' + repoInfo.repo + '/check-runs' +
                                  ' -f name="' + checkName + '"' +
                                  ' -f head_sha=' + headSha +
                                  ' -f status="' + status + '"' +
                                  (conclusion ? (' -f conclusion="' + conclusion + '"') : '') +
                                  (linkBlock.detailsUrl ?
