                        console.warn('  ⚠️  stamp "' + checkName + '" on ' +
                                     String(headSha).slice(0, 7) + ': ' + (e.message || e));
                    }
                });
            } finally {
                if (swapped && sourceTok) {
                    try { set_env_variable('GH_TOKEN', sourceTok); } catch (e2) {}
                }
            }
